sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
	c.viewEvent = function(eventId) {
        var url = '/event_management?id=event_details&sys_id=' + eventId;
        window.location.href = url;
    };

    c.rescheduleEvent = function(eventId) {
        var url = '/event_management?sys_id='+ eventId+'&view=sp&id=form&table=x_1790227_event_ma_event';
        window.location.href = url;
    };

    c.cancelEvent = function(eventId) {
        if(confirm('Are you sure you want to cancel this event?')) {
            alert('Cancel logic for Event ID: ' + eventId); 
        }
    };
};

sp_widget.css:
.upcoming-events-widget {
    background: #ffffff;
    padding: 25px;
    border-radius: 10px;
    box-shadow: 0 5px 15px rgba(0,0,0,0.1);
}
.upcoming-events-widget h3 {
    margin-bottom: 20px;
    font-weight: bold;
    color: #333;
}
.table th {
    background-color: #f8f9fa;
}
.label-success {
    background-color: #4caf50;
}
.label-warning {
    background-color: #ff9800;
}
.label-danger {
    background-color: #f44336;
}

sp_widget.script:
(function() {
    data.events = [];

    var now = new GlideDateTime(); // Current DateTime object

    var gr = new GlideRecord('x_1790227_event_ma_event'); 
    gr.addQuery('u_event_date', '>=', now); 
    gr.orderBy('u_event_date');
    gr.query();

    while(gr.next()) {
        data.events.push({
            sys_id: gr.getValue('sys_id'),
            name: gr.getValue('u_event_name'),
            date: gr.getDisplayValue('u_event_date'),
            location: gr.getValue('u_location'),
            status: gr.getDisplayValue('u_status')
        });
    }
})();
